/***************************************************************
 *  NODE: Skalowanie i publikacja
 *  
 *  OPIS:
 *  Ten node odbiera dane z Modbus (różne grupy rejestrów),
 *  przetwarza je (skalowanie, mapowanie, konwersje),
 *  a następnie publikuje do MQTT w formacie zgodnym z HA.
 *
 *  STRUKTURA:
 *  1. Funkcje pomocnicze
 *  2. Tryby pracy (główne + dodatkowe)
 *  3. Grupa podstawowa (temperatury, histerezy)
 *  4. Bity sterujące (coils)
 *  5. Czujniki FC3 (temperatury, ciśnienia, wydajności)
 *  6. Czujniki FC4 (sterowania + ZABEZPIECZENIE z ikoną)
 *  7. Parametry silnika
 *  8. Czas i harmonogram
 *  9. Krzywe grzewcze
 * 10. Binary inputs
 * 11. Alarmy 001–150
 * 12. Statusy
 *
 *  Każdy blok jest odseparowany i logicznie uporządkowany.
 ***************************************************************/

if (!Array.isArray(msg.payload)) return null;

let messages = [];

// --- FUNKCJE POMOCNICZE -------------------------------------

const scale = (v) => {
    if (v === undefined || v === null) return null;
    let signedVal = (v > 32767) ? v - 65536 : v;
    return Number((signedVal * 0.1).toFixed(1));
};

const noScale = (v) => (v !== undefined) ? Number(v) : null;


// =============================================================
// 1. TRYBY PRACY (GŁÓWNY TRYB POMPY)
// =============================================================

if (msg.topic === "tryb_pracy") {

    const map = {
        0: "Chłodzenie",
        1: "Ogrzewanie",
        2: "Chłodzenie+CWU",
        3: "Chłodzenie+CWU",
        4: "Ogrzewanie+CWU"
    };

    const val = noScale(msg.payload[0]);

    messages.push({
        topic: "sprsun/tryb_pracy/state",
        payload: map[val] ?? "Nieznany"
    });
}


// =============================================================
// 2. TRYBY DODATKOWE (POMPA + WENTYLATOR)
// =============================================================

else if (msg.topic === "tryby_dodatkowe") {

    const trybPompy = noScale(msg.payload[0]);
    const trybWent = noScale(msg.payload[1]);

    const trybyWentBack = {
        0: "Dzień",
        1: "Noc",
        2: "Krzywa grzewcza",
        3: "Serwisowy"
    };

    messages.push({
        topic: "sprsun/tryb_pompy_obiegowej/state",
        payload: trybPompy
    });

    messages.push({
        topic: "sprsun/tryb_wentylatora/state",
        payload: trybyWentBack[trybWent] ?? "Nieznany"
    });

    messages.push({
        topic: "sprsun/tryb_pracy_wentylatora/state",
        payload: trybyWentBack[trybWent] ?? "Nieznany"
    });
}


// =============================================================
// 3. GRUPA PODSTAWOWA (temperatury zadane, histerezy)
// =============================================================

else if (msg.topic === "grupa_podstawowa") {

    messages.push({ topic: "sprsun/ogrzewanie_temperatura_zadana/state", payload: scale(msg.payload[0]) });
    messages.push({ topic: "sprsun/chlodzenie_temperatura_zadana/state", payload: scale(msg.payload[1]) });
    messages.push({ topic: "sprsun/cwu_temperatura_zadana/state", payload: scale(msg.payload[2]) });
    messages.push({ topic: "sprsun/cwu_histereza_start/state", payload: scale(msg.payload[3]) });
    messages.push({ topic: "sprsun/cwu_histereza_stop/state", payload: scale(msg.payload[4]) });
    messages.push({ topic: "sprsun/co_histereza_start/state", payload: scale(msg.payload[5]) });
    messages.push({ topic: "sprsun/co_histereza_stop/state", payload: scale(msg.payload[6]) });
    messages.push({ topic: "sprsun/opoznienie_sprezarki/state", payload: noScale(msg.payload[12]) });
}


// =============================================================
// 4. COILS (bity sterujące)
// =============================================================

else if (msg.topic === "binary_coil_wlaczenie_pompy") {
    messages.push({
        topic: "sprsun/wlaczenie_pompy/state",
        payload: msg.payload[0] ? 1 : 0
    });
}

else if (msg.topic === "auto_start") {
    messages.push({
        topic: "sprsun/auto_start/state",
        payload: msg.payload[0] ? 1 : 0
    });
}

else if (msg.topic === "reset_alarmu") {
    messages.push({
        topic: "sprsun/reset_alarmu/state",
        payload: msg.payload[0] ? 1 : 0
    });
}

else if (msg.topic === "reset_parametrow") {
    messages.push({
        topic: "sprsun/reset_parametrow/state",
        payload: msg.payload[0] ? 1 : 0
    });
}


// =============================================================
// 5. CZUJNIKI FC3 (temperatury, ciśnienia, wydajności)
// =============================================================

else if (msg.topic === "czujniki_parametry") {

    const d = msg.payload;

    messages.push({ topic: "sprsun/temp_powrotu/state", payload: scale(d[0]) });
    messages.push({ topic: "sprsun/temp_zasilania/state", payload: scale(d[1]) });
    messages.push({ topic: "sprsun/temp_zewnetrzna/state", payload: scale(d[2]) });
    messages.push({ topic: "sprsun/temp_tloczenia/state", payload: scale(d[3]) });
    messages.push({ topic: "sprsun/temp_ssania/state", payload: scale(d[4]) });
    messages.push({ topic: "sprsun/cisnienie_tloczenia/state", payload: scale(d[5]) });
    messages.push({ topic: "sprsun/cisnienie_ssania/state", payload: scale(d[6]) });
    messages.push({ topic: "sprsun/temp_cwu/state", payload: scale(d[7]) });
    messages.push({ topic: "sprsun/temp_parownika/state", payload: scale(d[8]) });
    messages.push({ topic: "sprsun/pompka_pwm/state", payload: scale(d[10]) });
    messages.push({ topic: "sprsun/wentylator_1_pomiar/state", payload: noScale(d[12]) });
    messages.push({ topic: "sprsun/wentylator_2_pomiar/state", payload: noScale(d[14]) });
    messages.push({ topic: "sprsun/wymagana_wydajnosc/state", payload: noScale(d[15]) });
    messages.push({ topic: "sprsun/aktualna_wydajnosc/state", payload: noScale(d[16]) });
    messages.push({ topic: "sprsun/obroty_sprezarki/state", payload: noScale(d[17]) });
    messages.push({ topic: "sprsun/zawor_eev/state", payload: noScale(d[19]) });
    messages.push({ topic: "sprsun/przegrzanie/state", payload: scale(d[23]) });
    messages.push({ topic: "sprsun/aktualna_funkcja/state", payload: noScale(d[27]) });
    messages.push({ topic: "sprsun/temp_wyswietlacza/state", payload: scale(d[28]) });
    messages.push({ topic: "sprsun/status_id/state", payload: noScale(d[29]) });
}


// =============================================================
// 6. CZUJNIKI FC4 (sterowania + ZABEZPIECZENIE z ikoną)
// =============================================================

else if (msg.topic === "czujniki_input") {

    messages.push({ topic: "sprsun/wentylator_1_ster/state", payload: noScale(msg.payload[0]) });
    messages.push({ topic: "sprsun/wentylator_2_ster/state", payload: noScale(msg.payload[2]) });
    messages.push({ topic: "sprsun/status/state", payload: noScale(msg.payload[10]) });

    const raw = noScale(msg.payload[11]);

    const map = {
        0: "ok",
        1: "ok",
        2: "Niskie przegrzanie",
        3: "Niskie ciśnienie",
        4: "Wysokie ciśnienie",
        5: "Wysoka temp. skraplacza"
    };

    const text = map[raw] ?? "unknown";

    const icon = (text === "ok" || text === "unknown" || text === "unavailable")
        ? "mdi:shield-check"
        : "mdi:shield-alert";

    messages.push({ topic: "sprsun/zabezpieczenie/state", payload: text });
    messages.push({ topic: "sprsun/zabezpieczenie/icon", payload: icon });
}


// =============================================================
// 7. PARAMETRY SILNIKA
// =============================================================

else if (msg.topic === "nowe_parametry_silnika") {

    const d = msg.payload;

    messages.push({ topic: "sprsun/program_version_1/state", payload: noScale(d[0]) });
    messages.push({ topic: "sprsun/program_version_2/state", payload: noScale(d[1]) });
    messages.push({ topic: "sprsun/program_version_3/state", payload: noScale(d[2]) });
    messages.push({ topic: "sprsun/hp_model_1/state", payload: noScale(d[3]) });
    messages.push({ topic: "sprsun/hp_model_2/state", payload: noScale(d[4]) });
    messages.push({ topic: "sprsun/silnik_moc/state", payload: noScale(d[8]) });
    messages.push({ topic: "sprsun/silnik_napiecie/state", payload: noScale(d[9]) });
    messages.push({ topic: "sprsun/silnik_prad/state", payload: noScale(d[10]) });
}


// =============================================================
// 8. CZAS I DATA
// =============================================================

else if (msg.topic === "dzien_tygodnia") {
    messages.push({ topic: "sprsun/czas_dzien_tydzien/state", payload: noScale(msg.payload[0]) });
}

else if (msg.topic === "data_czas") {
    messages.push({ topic: "sprsun/czas_rok/state", payload: noScale(msg.payload[0]) });
    messages.push({ topic: "sprsun/czas_miesiac/state", payload: noScale(msg.payload[1]) });
    messages.push({ topic: "sprsun/czas_dzien_miesiaca/state", payload: noScale(msg.payload[2]) });
    messages.push({ topic: "sprsun/czas_godzina/state", payload: noScale(msg.payload[3]) });
    messages.push({ topic: "sprsun/czas_minuta/state", payload: noScale(msg.payload[4]) });
}


// =============================================================
// 9. HARMONOGRAM
// =============================================================

else if (msg.topic === "harmonogram_tygodniowy") {

    const dni = ["poniedzialek", "wtorek", "sroda", "czwartek", "piatek", "sobota", "niedziela"];

    for (let i = 0; i < 7; i++) {
        messages.push({ topic: `sprsun/timer_${dni[i]}_godz_wl/state`, payload: noScale(msg.payload[i * 2]) });
        messages.push({ topic: `sprsun/timer_${dni[i]}_min_wl/state`, payload: noScale(msg.payload[i * 2 + 1]) });
        messages.push({ topic: `sprsun/timer_${dni[i]}_godz_wyl/state`, payload: noScale(msg.payload[i * 2 + 14]) });
        messages.push({ topic: `sprsun/timer_${dni[i]}_min_wyl/state`, payload: noScale(msg.payload[i * 2 + 15]) });
    }
}


// =============================================================
// 10. KRZYWE GRZEWCZE
// =============================================================

else if (msg.topic === "krzywe_blok_1") {

    const d = msg.payload;

    messages.push({ topic: "sprsun/chlodzenie_krzywa_temp_zew_x1/state", payload: scale(d[0]) });
    messages.push({ topic: "sprsun/chlodzenie_krzywa_temp_zew_x2/state", payload: scale(d[1]) });
    messages.push({ topic: "sprsun/chlodzenie_krzywa_temp_zew_x3/state", payload: scale(d[2]) });
    messages.push({ topic: "sprsun/chlodzenie_krzywa_temp_zew_x4/state", payload: scale(d[3]) });

    messages.push({ topic: "sprsun/ogrzewanie_krzywa_temp_zew_x1/state", payload: scale(d[4]) });
    messages.push({ topic: "sprsun/ogrzewanie_krzywa_temp_zew_x2/state", payload: scale(d[5]) });
    messages.push({ topic: "sprsun/ogrzewanie_krzywa_temp_zew_x3/state", payload: scale(d[6]) });
    messages.push({ topic: "sprsun/ogrzewanie_krzywa_temp_zew_x4/state", payload: scale(d[7]) });

    messages.push({ topic: "sprsun/cwu_krzywa_temp_zew_x1/state", payload: scale(d[8]) });
    messages.push({ topic: "sprsun/cwu_krzywa_temp_zew_x2/state", payload: scale(d[9]) });
    messages.push({ topic: "sprsun/cwu_krzywa_temp_zew_x3/state", payload: scale(d[10]) });
    messages.push({ topic: "sprsun/cwu_krzywa_temp_zew_x4/state", payload: scale(d[11]) });

    messages.push({ topic: "sprsun/chlodzenie_krzywa_temp_zasilania_y2/state", payload: scale(d[12]) });
    messages.push({ topic: "sprsun/chlodzenie_krzywa_temp_zasilania_y3/state", payload: scale(d[13]) });
    messages.push({ topic: "sprsun/chlodzenie_krzywa_temp_zasilania_y4/state", payload: scale(d[14]) });

    messages.push({ topic: "sprsun/ogrzewanie_krzywa_temp_zasilania_y1/state", payload: scale(d[15]) });
    messages.push({ topic: "sprsun/ogrzewanie_krzywa_temp_zasilania_y2/state", payload: scale(d[16]) });
    messages.push({ topic: "sprsun/ogrzewanie_krzywa_temp_zasilania_y3/state", payload: scale(d[17]) });

    messages.push({ topic: "sprsun/cwu_krzywa_temp_zasilania_y1/state", payload: scale(d[18]) });
    messages.push({ topic: "sprsun/cwu_krzywa_temp_zasilania_y2/state", payload: scale(d[19]) });
    messages.push({ topic: "sprsun/cwu_krzywa_temp_zasilania_y3/state", payload: scale(d[20]) });
    messages.push({ topic: "sprsun/cwu_krzywa_temp_zasilania_y4/state", payload: scale(d[21]) });
}

else if (msg.topic === "krzywe_blok_2") {
    messages.push({ topic: "sprsun/ogrzewanie_krzywa_temp_zasilania_y4/state", payload: scale(msg.payload[0]) });
}


// =============================================================
// 11. BINARY INPUTS
// =============================================================

else if (msg.topic === "binary_inputs_blok_1") {

    const d = msg.payload;

    const topics = [
        "zasilanie", "czujnik_przeplywu", "we_sterowania_zewnetrznego",
        "we_sterowania_ac", "we_faza_zasilania", "wy_wysoka_predk_wentylatora",
        "wy_niska_predk_wentylatora", "wy_zawor_4_drogowy", "pompa_obiegowa",
        "grzalka_obudowy", "grzalka_sprezarki", "zawor_trojdrogowy", "grzalka"
    ];

    topics.forEach((name, i) => {
        messages.push({ topic: `sprsun/${name}/state`, payload: d[i] ? 1 : 0 });
    });
}

else if (msg.topic === "binary_input_pompka") {
    messages.push({ topic: "sprsun/pompka_obiegowa_status/state", payload: msg.payload[0] ? 1 : 0 });
}

else if (msg.topic === "binary_coils_blok") {
    messages.push({ topic: "sprsun/defrost/state", payload: msg.payload[0] ? 1 : 0 });
    messages.push({ topic: "sprsun/strefy_czasowe/state", payload: msg.payload[2] ? 1 : 0 });
    messages.push({ topic: "sprsun/program_tygodniowy/state", payload: msg.payload[3] ? 1 : 0 });
}


// =============================================================
// 12. ALARMY 001–056
// =============================================================

else if (msg.topic === "binary_alarmy_blok") {

    const d = msg.payload;

    for (let i = 1; i <= 56; i++) {
        let alarmId = i.toString().padStart(3, "0");

        if (d[i - 1] !== undefined) {
            messages.push({
                topic: `sprsun/alarm/${alarmId}/state`,
                payload: d[i - 1] ? 1 : 0
            });
        }
    }
}


// =============================================================
// 13. ALARMY 057–150
// =============================================================

else if (msg.topic === "binary_alarmy_blok_2") {

    const d = msg.payload;

    for (let i = 57; i <= 150; i++) {
        let idx = i - 57;
        let alarmId = i.toString().padStart(3, "0");

        if (d[idx] !== undefined) {
            messages.push({
                topic: `sprsun/alarm/${alarmId}/state`,
                payload: d[idx] ? 1 : 0
            });
        }
    }
}


// =============================================================
// 14. STATUSY (sprężarka, wentylator, wejścia, pompa 2)
// =============================================================

else if (msg.topic === "binary_statusy_blok") {

    const d = msg.payload;

    const topics = [
        "sprezarka_stan",
        "wentylator_stan",
        "we_chlodzenie",
        "we_ogrzewania",
        "wy_pompa_obiegowa_2"
    ];

    topics.forEach((name, i) => {
        messages.push({
            topic: `sprsun/${name}/state`,
            payload: d[i] ? 1 : 0
        });
    });
}


// =============================================================
// ZWROT WYNIKU
// =============================================================

return [messages.filter(m => m.payload !== null)];

/***************************************************************
 *  System: Sprsun CGK040-V3L
 *  Integracja: Home Assistant (MQTT Discovery)
 *  Autor: Arkadiusz + Copilot
 *
 *  OPIS:
 *  Ten moduł generuje pełną konfigurację MQTT Discovery
 *  dla Home Assistant, obejmując:
 *
 *   • Sensory (analogowe, liczbowe, tekstowe)
 *   • Binary sensors (wejścia, wyjścia, statusy)
 *   • Selects (tryby pracy)
 *   • Switches (coils)
 *   • Buttons (akcje jednorazowe)
 *   • Alarmy 001–150 (binary_sensor)
 *   • Liczniki i statystyki
 *
 *  Całość generowana jest dynamicznie z tablic konfiguracyjnych,
 *  co zapewnia:
 *   – brak duplikacji kodu
 *   – łatwą rozbudowę
 *   – pełną spójność z Node‑RED i Modbus
 *
 ***************************************************************/


/***************************************************************
 * 1. DEFINICJA URZĄDZENIA (Home Assistant → Device Registry)
 ***************************************************************/
const device = {
    identifiers: ["sprsun_cgk040_v3l"],   // unikalny identyfikator urządzenia
    name: "Sprsun CGK040-V3L",            // nazwa widoczna w HA
    manufacturer: "Sprsun",               // producent
    model: "CGK040-V3L"                   // model urządzenia
};


/***************************************************************
 * 2. FUNKCJE POMOCNICZE
 ***************************************************************/
let messages = [];

/**
 * addDiscovery()
 * Funkcja pomocnicza do publikacji konfiguracji MQTT Discovery.
 *
 * @param {string} topic  – pełny topic discovery
 * @param {object} payload – obiekt JSON konfiguracyjny
 */
function addDiscovery(topic, payload) {
    messages.push({
        topic,
        payload: JSON.stringify(payload),
        retain: true
    });
}


/***************************************************************
 * 3. SENSORY (Analogowe, liczbowe, tekstowe)
 *
 * Każdy element tablicy opisuje jeden sensor:
 *   id  – identyfikator MQTT (sprsun/<id>/state)
 *   n   – nazwa encji w HA
 *   u   – jednostka (opcjonalnie)
 *   c   – device_class (opcjonalnie)
 *   icon_topic – dynamiczna ikona (opcjonalnie)
 ***************************************************************/
const sensors = [

    /* --- Tryby i statusy tekstowe --- */
    { id: "tryb_pracy", n: "Tryb pracy" },
    { id: "tryb_pompy_obiegowej", n: "Tryb pompy obiegowej" }, // status tekstowy
    { id: "tryb_wentylatora", n: "Tryb wentylatora" },

    /* --- Temperatury --- */
    { id: "temp_powrotu", n: "Temperatura powrotu", u: "°C", c: "temperature" },
    { id: "temp_zasilania", n: "Temperatura zasilania", u: "°C", c: "temperature" },
    { id: "temp_zewnetrzna", n: "Temperatura zewnętrzna", u: "°C", c: "temperature" },
    { id: "temp_tloczenia", n: "Temperatura tłoczenia", u: "°C", c: "temperature" },
    { id: "temp_ssania", n: "Temperatura ssania", u: "°C", c: "temperature" },
    { id: "temp_cwu", n: "Temperatura CWU", u: "°C", c: "temperature" },
    { id: "temp_parownika", n: "Temperatura parownika", u: "°C", c: "temperature" },

    /* --- Ciśnienia --- */
    { id: "cisnienie_tloczenia", n: "Ciśnienie tłoczenia", u: "bar", c: "pressure" },
    { id: "cisnienie_ssania", n: "Ciśnienie ssania", u: "bar", c: "pressure" },

    /* --- Sterowanie PWM --- */
    { id: "pompka_pwm", n: "Pompka PWM", u: "%" },

    /* --- Wentylatory --- */
    { id: "wentylator_1_ster", n: "Wentylator 1 sterowanie" },
    { id: "wentylator_1_pomiar", n: "Wentylator 1 pomiar" },
    { id: "wentylator_2_ster", n: "Wentylator 2 sterowanie" },
    { id: "wentylator_2_pomiar", n: "Wentylator 2 pomiar" },

    /* --- Wydajność i sprężarka --- */
    { id: "wymagana_wydajnosc", n: "Wymagana wydajność" },
    { id: "aktualna_wydajnosc", n: "Aktualna wydajność" },
    { id: "obroty_sprezarki", n: "Obroty sprężarki", u: "RPM" },
    { id: "zawor_eev", n: "Zawór EEV" },

    /* --- Statusy --- */
    { id: "status", n: "Status" },

    /* --- Zabezpieczenie (dynamiczna ikona) --- */
    {
        id: "zabezpieczenie",
        n: "Zabezpieczenie",
        icon_topic: "sprsun/zabezpieczenie/icon"
    },

    /* --- Pozostałe parametry --- */
    { id: "przegrzanie", n: "Przegrzanie", u: "°C", c: "temperature" },
    { id: "aktualna_funkcja", n: "Aktualna funkcja" },
    { id: "temp_wyswietlacza", n: "Temperatura wyświetlacza", u: "°C", c: "temperature" },
    { id: "status_id", n: "Status ID" },

    /* --- Wersje i modele --- */
    { id: "program_version_1", n: "Program version 1" },
    { id: "program_version_2", n: "Program version 2" },
    { id: "program_version_3", n: "Program version 3" },
    { id: "hp_model_1", n: "HeatPump model 1" },
    { id: "hp_model_2", n: "HeatPump model 2" },

    /* --- Parametry silnika --- */
    { id: "silnik_moc", n: "Silnik moc", u: "W", c: "power" },
    { id: "silnik_napiecie", n: "Silnik napięcie", u: "V", c: "voltage" },
    { id: "silnik_prad", n: "Silnik prąd", u: "A", c: "current" }
];

/* --- Rejestracja sensorów --- */
sensors.forEach(s => {
    let cfg = {
        name: s.n,
        unique_id: "sprsun_" + s.id,
        state_topic: "sprsun/" + s.id + "/state",
        device
    };

    if (s.u) cfg.unit_of_measurement = s.u;
    if (s.c) cfg.device_class = s.c;
    if (s.icon_topic) cfg.icon = s.icon_topic;

    addDiscovery(`homeassistant/sensor/sprsun/${s.id}/config`, cfg);
});


/***************************************************************
 * 4. SELECTS (Tryby pracy)
 *
 *  Każdy select odpowiada za parametr ustawialny Modbus.
 ***************************************************************/

/* --- Tryb pracy główny --- */
addDiscovery("homeassistant/select/sprsun/tryb_pracy/config", {
    name: "Tryb pracy",
    unique_id: "sprsun_tryb_pracy",
    state_topic: "sprsun/tryb_pracy/state",
    command_topic: "sprsun/tryb_pracy/set",
    options: [
        "Chłodzenie",
        "Ogrzewanie",
        "CWU",
        "Chłodzenie+CWU",
        "Ogrzewanie+CWU"
    ],
    device
});

/* --- Tryb pracy wentylatora --- */
