    outputs.push(
        { topic: "sprsun/ilosc_wlaczen_dzisiaj/state", payload: daily_on, retain: true },
        { topic: "sprsun/ilosc_wlaczen/state", payload: total_on, retain: true },
        { topic: "sprsun/ilosc_wlaczen_w_tym_miesiacu/state", payload: month_on, retain: true },
        { topic: "sprsun/ilosc_wlaczen_w_tym_roku/state", payload: year_on, retain: true }
    );

    return outputs;
}


/***************************************************************
 * 6. ZDARZENIE: ZAWÓR 3D
 *    msg.data === "zmiana trybu pracy"
 ***************************************************************/
if (msg.data === "zmiana trybu pracy") {

    valve_3d++;

    flow.set("zawor_3d_ilosc_przelaczen_od_poczatku_montazu", valve_3d);

    outputs.push(
        { topic: "sprsun/zawor_3d_ilosc_przelaczen_od_poczatku_montazu/state", payload: valve_3d, retain: true }
    );

    return outputs;
}


/***************************************************************
 * 7. ZDARZENIE: ZWIĘKSZANIE CZASU POSIADANIA
 *    msg.topic === "czas_posiadania"
 ***************************************************************/
if (msg.topic === "czas_posiadania") {

    days_owned++;

    flow.set("czas_posiadania", days_owned);

    outputs.push(
        { topic: "sprsun/czas_posiadania/state", payload: days_owned, retain: true }
    );

    return outputs;
}


/***************************************************************
 * 8. Brak dopasowania → brak publikacji
 ***************************************************************/
return [];

/***************************************************************
 *  NODE: Aktywne alarmy (agregacja alarmów 001–150)
 *
 *  OPIS:
 *  Ten node odbiera pojedyncze komunikaty MQTT:
 *      sprsun/alarm/<ID>/state
 *  gdzie <ID> to numer alarmu 001–150.
 *
 *  Zadania noda:
 *   1. Utrzymywać w pamięci flow listę aktywnych alarmów.
 *   2. Aktualizować listę przy każdym przychodzącym alarmie.
 *   3. Generować zbiorczy tekst:
 *        • "Brak" — jeśli nie ma aktywnych alarmów
 *        • "Alarm 023, Alarm 041, Alarm 118" — jeśli są
 *   4. Publikować wynik do:
 *        sprsun/aktywny_alarm/state
 *
 *  Pamięć:
 *      flow.activeAlarms = { "023": true, "041": true, ... }
 *
 ***************************************************************/


/***************************************************************
 * 1. Pobranie aktualnej listy aktywnych alarmów z pamięci flow
 ***************************************************************/
let active = flow.get("activeAlarms") || {};


/***************************************************************
 * 2. Dopasowanie numeru alarmu z tematu MQTT
 *    Przykład:
 *      sprsun/alarm/057/state → "057"
 ***************************************************************/
let match = msg.topic.match(/alarm\/(\d{3})\/state/);
if (!match) return null;

let alarmId = match[1];
let value = Number(msg.payload);


/***************************************************************
 * 3. Aktualizacja listy aktywnych alarmów
 *
 *    value = 1 → alarm aktywny
 *    value = 0 → alarm nieaktywny
 ***************************************************************/
if (value === 1) {
    active[alarmId] = true;
} else {
    delete active[alarmId];
}

flow.set("activeAlarms", active);


/***************************************************************
 * 4. Sortowanie aktywnych alarmów rosnąco
 ***************************************************************/
let keys = Object.keys(active).sort();


/***************************************************************
 * 5. Jeśli brak alarmów → zwróć "Brak"
 ***************************************************************/
if (keys.length === 0) {
    return {
        topic: "sprsun/aktywny_alarm/state",
        payload: "Brak"
    };
}


/***************************************************************
 * 6. Jeśli są alarmy → zbuduj listę:
 *      "Alarm 023, Alarm 041, Alarm 118"
 ***************************************************************/
let text = keys.map(k => `Alarm ${k}`).join(", ");


/***************************************************************
 * 7. Zwrócenie zbiorczego komunikatu
 ***************************************************************/
return {
    topic: "sprsun/aktywny_alarm/state",
    payload: text
};

// Usuwanie encji alarmów w starym formacie:
// - alarm_001
// - alarm_001_2
// - alarm_002
// - alarm_002_2
// ...
// - alarm_150_2

let msgs = [];

for (let i = 1; i <= 150; i++) {
    const alarmId = i.toString().padStart(3, "0");

    // Stary format bez dopisku _2
    msgs.push({
        topic: `homeassistant/binary_sensor/sprsun/alarm_${alarmId}/config`,
        payload: "",
        retain: true
    });

    // Stary format z dopiskiem _2
    msgs.push({
        topic: `homeassistant/binary_sensor/sprsun/alarm_${alarmId}_2/config`,
        payload: "",
        retain: true
    });
}

// Usuwanie starych encji switch dla resetów
msgs.push({
    topic: "homeassistant/switch/sprsun/reset_alarmu/config",
    payload: "",
    retain: true
});

msgs.push({
    topic: "homeassistant/switch/sprsun/reset_parametrow/config",
    payload: "",
    retain: true
});

return [msgs];

/***************************************************************
 *  NODE: Router zdarzeń z Home Assistant
 *
 *  OPIS:
 *  Ten node odbiera zdarzenia z HA (entity_id + payload)
 *  i kieruje je na odpowiednie wyjścia w zależności od typu
 *  wykrytego zdarzenia.
 *
 *  Wejście:
 *      msg.entity_id  – encja HA (binary_sensor.*)
 *      msg.payload    – "on" / "off"
 *
 *  Wyjścia:
 *      OUTPUT 1 → zdarzenia dla modułu liczników
 *      OUTPUT 2 → zdarzenia dla modułu defrostu / wentylatora
 *
 *  Logika:
 *   • Sprężarka ON → "uruchomienie pompy"
 *   • Zawór 3D ON → "zmiana trybu pracy"
 *   • Wentylator OFF → "wentylator_stop"
 *
 *  Jeśli zdarzenie nie pasuje do żadnego wzorca → oba wyjścia null.
 *
 ***************************************************************/


/***************************************************************
 * 1. Pobranie danych wejściowych
 ***************************************************************/
let entity = msg.entity_id;
let state  = msg.payload;


/***************************************************************
 * 2. ZDARZENIE: Sprężarka → uruchomienie pompy
 *
 *  binary_sensor.sprsun_cgk040_v3l_sprezarka_stan
 *      on  → pompa została uruchomiona
 *      off → ignorujemy
 ***************************************************************/
if (entity === "binary_sensor.sprsun_cgk040_v3l_sprezarka_stan") {
    if (state === "on") {
        msg.data = "uruchomienie pompy";
        return [ msg , null ];   // → WYJŚCIE 1 (liczniki)
    }
}


/***************************************************************
 * 3. ZDARZENIE: Zawór 3D → zmiana trybu pracy
 *
 *  binary_sensor.sprsun_cgk040_v3l_zawor_trojdrogowy
 *      on  → zawór zmienił pozycję
 ***************************************************************/
if (entity === "binary_sensor.sprsun_cgk040_v3l_zawor_trojdrogowy") {
    if (state === "on") {
        msg.data = "zmiana trybu pracy";
        return [ msg , null ];   // → WYJŚCIE 1 (liczniki)
    }
}


/***************************************************************
 * 4. ZDARZENIE: Wentylator → możliwy defrost
 *
 *  binary_sensor.sprsun_cgk040_v3l_wentylator_stan
 *      off → wentylator zatrzymał się (początek defrostu)
 ***************************************************************/
if (entity === "binary_sensor.sprsun_cgk040_v3l_wentylator_stan") {
    if (state === "off") {
        msg.data = "wentylator_stop";
        return [ null , msg ];   // → WYJŚCIE 2 (moduł defrostu)
    }
}


/***************************************************************
 * 5. Brak dopasowania → oba wyjścia null
 ***************************************************************/
return [ null , null ];
